Hier ist ein Beispiel C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

using namespace std;

int main() {
    // Benutzer eingegebenes Wort und Dateiname
    string word, filename;
    cout << "Bitte geben Sie das zu suchende Wort und den Dateinamen ein: ";
    cin >> word >> filename;

    // Map zum Speichern der Vorkommnisse des Wortes
    map<string, int> wordCount;

    // Datei öffnen und lesen
    ifstream file(filename);
    if (!file.is_open()) {
        cout << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) {
        // Wörter der aktuellen Zeile in eine Vektorliste splitten
        vector<string> words;
        size_t pos = 0;
        while ((pos = line.find(" ")) != string::npos) {
            words.push_back(line.substr(0, pos));
            line.erase(0, pos + 1);
        }
        words.push_back(line);

        // Vorkommen des Suchworts zählen und in die Map speichern
        for (auto& w : words) {
            if (w == word) {
                wordCount[word]++;
            }
        }
    }

    // Ergebnisse ausgeben
    if (wordCount[word] > 0) {
        cout << "Das Wort '" << word << "' tritt " << wordCount[word] << " Mal in der Datei '" << filename << "' auf." << endl;
    } else {
        cout << "Das Wort '" << word << "' tritt nicht in der Datei '" << filename << "' auf." << endl;
    }

    file.close();
    return 0;
}
```

Das Programm erfordert die folgenden Bibliotheken:

- `<iostream>`: Standard-Eingabe- und Ausgabe-Bibliothek
- `<fstream>`: Datei-Eingabe- und Ausgabe-Bibliothek
